            "childMeaning": "భీష్ముడు, పెద్ద కౌరవుడు, దుర్యోధనుణ్ణి ఉత్సాహపరచడానికి గట్టిగా శంఖం పూరించాడు.",
            "activity": "సింహం గర్జనలా గట్టిగా శబ్దం చేయండి (వినోదం కోసం)."
